INSERT INTO public.legal_audit_sources(id,version,body,created_by) VALUES('codigo-civil',1,'{"id": "codigo-civil", "title": "Código Civil — Lei 10.406/2002", "authority": "Congresso Nacional / Câmara dos Deputados", "kind": "LEI", "url": "https://www2.camara.leg.br/legin/fed/lei/2002/lei-10406-10-janeiro-2002-432893-normaatualizada-pl.html", "edition": "Trechos dos arts. 286, 299, 413, 422 e 423; não é reprodução integral", "validFrom": "2003-01-11", "validTo": null, "topics": ["CESSAO", "PENALIDADE", "AMBIGUIDADE", "RESPONSABILIDADE"], "state": "PUBLISHED", "text": "Art. 286. O credor pode ceder o seu crédito, se a isso não se opuser a natureza da obrigação, a lei, ou a convenção com o devedor; a cláusula proibitiva da cessão não poderá ser oposta ao cessionário de boa-fé, se não constar do instrumento da obrigação.\nArt. 299. É facultado a terceiro assumir a obrigação do devedor, com o consentimento expresso do credor, ficando exonerado o devedor primitivo, salvo se aquele, ao tempo da assunção, era insolvente e o credor o ignorava.\nArt. 413. A penalidade deve ser reduzida eqüitativamente pelo juiz se a obrigação principal tiver sido cumprida em parte, ou se o montante da penalidade for manifestamente excessivo, tendo-se em vista a natureza e a finalidade do negócio.\nArt. 422. Os contratantes são obrigados a guardar, assim na conclusão do contrato, como em sua execução, os princípios de probidade e boa-fé.\nArt. 423. Quando houver no contrato de adesão cláusulas ambíguas ou contraditórias, dever-se-á adotar a interpretação mais favorável ao aderente.", "reviewedOn": "2026-11-17", "hash": "38da876e0125d43e1d4644e143b87b2de873ff0335df57cbca547b48272802ae"}'::jsonb,'SOURCE_REVIEW_20261117');
INSERT INTO public.legal_audit_sources(id,version,body,created_by) VALUES('lei-seguros',1,'{"id": "lei-seguros", "title": "Lei 15.040/2024 — contratos de seguro", "authority": "Congresso Nacional / Câmara dos Deputados", "kind": "LEI", "url": "https://www2.camara.leg.br/legin/fed/lei/2024/lei-15040-9-dezembro-2024-796661-publicacaooriginal-173706-pl.html", "edition": "Trechos dos arts. 1º, 2º e 134; aplicação temporal a conferir no contrato", "validFrom": "2025-12-11", "validTo": null, "topics": ["GARANTIA"], "state": "PUBLISHED", "text": "Art. 1º Pelo contrato de seguro, a seguradora obriga-se, mediante o pagamento do prêmio equivalente, a garantir interesse legítimo do segurado ou do beneficiário contra riscos predeterminados.\nArt. 2º Somente podem pactuar contratos de seguro entidades que se encontrem devidamente autorizadas na forma da lei.\nArt. 134. Esta Lei entra em vigor após decorrido 1 (um) ano de sua publicação oficial.", "reviewedOn": "2026-11-17", "hash": "5d6ef48eaf5a10a44b61edc5703ee875e69f53f367b69451b7ce17021eb63a4c"}'::jsonb,'SOURCE_REVIEW_20261117');
INSERT INTO public.legal_audit_sources(id,version,body,created_by) VALUES('ccee-contratos-2026',1,'{"id": "ccee-contratos-2026", "title": "CCEE — Regras de Comercialização, caderno 05 Contratos", "authority": "CCEE / aprovação ANEEL", "kind": "REGRA_CCEE", "url": "https://www.ccee.org.br/documents/80415/31259220/05%20-%20Contratos_2026.5.1_MAI.pdf/e5d55e8a-f760-236f-b1e1-ee4eea31b9ef", "edition": "2026.5.1 — trecho 12.4.1, item 120; verificar alterações posteriores", "validFrom": "2026-05-01", "validTo": "2026-12-31", "topics": ["CESSAO", "VOLUME", "REPRESENTACAO"], "state": "PUBLISHED", "text": "120. A cessão deverá ser formalizada por meio de Contrato Bilateral de Cessão a ser registrado e validado na CCEE. No entanto, para o registro do Contrato Bilateral de Cessão, os Contratos Originais de Compra e Venda de Energia Elétrica deverão estar previamente registrados e validados na CCEE.\n120.1. A Cessão de Montantes de Energia Elétrica e de Potência estará limitada à quantidade e ao prazo final do Contrato Original de Compra e Venda de Energia Elétrica registrado e validado, cabendo a verificação de tal limitação pela CCEE para a efetivação dos contratos.", "reviewedOn": "2026-11-17", "hash": "24b02606288e50d692a1fc87318097d820dce67dc2208d7d197bda15d2a87512"}'::jsonb,'SOURCE_REVIEW_20261117');
