INSERT INTO public.legal_audit_sources(id,version,body,created_by) VALUES('mme50',1,'{"id": "mme50", "title": "Portaria Normativa MME 50/2022 — opção ACL", "authority": "MME", "kind": "PORTARIA", "url": "https://www.gov.br/mme/pt-br/acesso-a-informacao/legislacao/portarias/2022/portaria-normativa-n-50-gm-mme-2022.pdf", "edition": "Art. 1º §§ 1º e 2º; não define sozinho todas as regras atuais de migração", "validFrom": "2024-01-01", "validTo": null, "topics": ["REPRESENTACAO"], "state": "PUBLISHED", "text": "§ 1º A partir de 1º de janeiro de 2024, os consumidores classificados como Grupo A, nos termos da regulamentação vigente, poderão optar pela compra de energia elétrica a qualquer concessionário, permissionário ou autorizado de energia elétrica do Sistema Interligado Nacional.\n§ 2º Os consumidores de que trata o § 1º com carga individual inferior a 500kW, no exercício da opção de que tratam os arts. 15 e 16 da Lei nº 9.074, de 7 de julho de 1995, serão representados por agente varejista perante a Câmara de Comercialização de Energia Elétrica - CCEE.", "reviewedOn": "2026-11-17", "hash": "2f85d3401f6f33949d378858bf1c5be407ba13c0e220fc45e131bc89d725d1f3"}'::jsonb,'SOURCE_REVIEW_20261117');
